/* Inhalte Teil 5: Erde & Klima, Politik & Recht, Mathe & Logik, Sprache & Rhetorik */

/* ===================== ERDE & KLIMA ===================== */
WF.add({
  id: "er-plattentektonik", cat: "erde", min: 6, wiki: "Plattentektonik", tags: ["Kontinente", "Erdbeben", "Vulkane", "Wegener", "Geologie"],
  title: "Plattentektonik: Die Erde in Bewegung",
  hook: "Die Kontinente wandern, so schnell wie deine Fingernägel wachsen. Ein Deutscher hat das entdeckt und wurde dafür ausgelacht.",
  cards: [
    { h: "Der Mann, dem keiner glaubte", t: "Schon beim Blick auf eine Weltkarte fällt es auf: Die Ostküste Südamerikas passt fast wie ein Puzzleteil an die Westküste Afrikas. Der deutsche Meteorologe **Alfred Wegener** aus Marburg zog daraus 1912 eine kühne Folgerung: Alle Kontinente bildeten einst einen einzigen Urkontinent, **Pangäa**, und sind seitdem auseinandergedriftet.\n\nEr hatte gute Belege: Fossilien desselben Reptils, des **Mesosaurus**, fand man in Südamerika und in Afrika, obwohl es niemals über einen Ozean hätte schwimmen können. Trotzdem lachten viele Geologen ihn aus, weil er nicht erklären konnte, **welche Kraft** Kontinente bewegen soll. Wegener starb 1930 auf einer Expedition in Grönland. Erst in den 1960er Jahren bekam er recht.", merke: "Alfred Wegener beschrieb 1912 die Kontinentaldrift und den Urkontinent Pangäa." },
    { h: "Ein Planet in Schichten", t: "Die Erde ist aufgebaut wie ein Pfirsich. Außen liegt die **Kruste**, im Verhältnis zur ganzen Erde dünner als die Schale eines Apfels. Darunter folgt der **Mantel**, rund 2.900 Kilometer dick, aus heißem Gestein, das sich über Jahrmillionen wie extrem zäher Teig bewegt. Ganz innen liegt der **Kern** aus Eisen und Nickel: außen flüssig, innen fest und mit über 5.000 Grad ungefähr so heiß wie die Oberfläche der Sonne.\n\nDie Kruste ist in große **Platten** zerbrochen, die auf dem Mantel treiben. Wärmeströme im Mantel schieben und ziehen sie. Sie bewegen sich nur wenige **Zentimeter pro Jahr**, etwa so schnell, wie deine Fingernägel wachsen.", merke: "Die Erdplatten treiben auf dem Mantel und bewegen sich wenige Zentimeter pro Jahr." },
    { h: "Was an den Rändern passiert", t: "Spannend wird es dort, wo Platten aufeinandertreffen. Es gibt drei Arten von Grenzen:\n\n**Auseinander**: Platten driften voneinander weg, Magma steigt nach. Mitten durch den Atlantik zieht sich so ein Gebirge, der **Mittelatlantische Rücken**. Auf **Island** kann man ihn an Land sehen und zwischen zwei Platten spazieren.\n\n**Gegeneinander**: Platten stoßen zusammen. Taucht eine unter die andere ab, entstehen Tiefseegräben und Vulkane. Prallen zwei Kontinente aufeinander, falten sich Gebirge auf. Der **Himalaya** entstand, weil Indien gegen Asien drückt, und er wächst noch immer.\n\n**Aneinander vorbei**: Platten schrammen seitlich entlang, wie an der **San-Andreas-Verwerfung** in Kalifornien.", merke: "Der Himalaya entsteht, weil die Indische Platte gegen Asien drückt.",
      check: { q: "Warum wächst der Himalaya immer noch?", o: ["Weil die Indische Platte weiter gegen Asien drückt", "Weil dort Vulkane ausbrechen", "Weil sich Schnee darauf ansammelt"], a: 0, e: "Die Kollision zweier Kontinentalplatten faltet die Kruste nach oben." } },
    { h: "Wenn sich Spannung entlädt", t: "Platten gleiten nicht gleichmäßig. Oft verhaken sie sich, Spannung baut sich über Jahre auf und entlädt sich dann plötzlich: ein **Erdbeben**. Gemessen wird die Stärke heute mit der **Momenten-Magnitude**, die die bekannte Richterskala abgelöst hat. Jede Stufe mehr bedeutet etwa die **32-fache Energie**. Ein Beben der Stärke 7 setzt also rund 1.000-mal so viel Energie frei wie eins der Stärke 5.\n\nDas stärkste je gemessene Beben erschütterte **1960 Chile** mit Magnitude **9,5**. Auch Deutschland ist nicht ganz ruhig: Der **Oberrheingraben** zwischen Basel und Frankfurt ist ein Grabenbruch, in dem es gelegentlich leichte Beben gibt.", merke: "Eine Magnitude mehr bedeutet etwa 32-mal so viel Energie." },
    { h: "Die Welt in 200 Millionen Jahren", t: "Die Plattentektonik hört nie auf. Der **Atlantik** wird jedes Jahr ein paar Zentimeter breiter, Europa und Nordamerika entfernen sich also voneinander. In **Ostafrika** reißt der Kontinent entlang des **Ostafrikanischen Grabenbruchs** langsam auseinander. In Millionen Jahren könnte dort ein neues Meer entstehen.\n\nGeologen rechnen damit, dass sich die Kontinente in etwa 200 bis 250 Millionen Jahren wieder zu einem neuen **Superkontinent** zusammenschieben. Wie er aussehen wird, ist umstritten. Pangäa war übrigens nicht der erste: Superkontinente haben sich in der Erdgeschichte schon mehrfach gebildet und wieder aufgelöst.", merke: "In etwa 200 bis 250 Millionen Jahren könnte ein neuer Superkontinent entstehen." },
  ],
  quiz: [
    { t: "gap", q: "Der Urkontinent, aus dem die heutigen Kontinente entstanden, heißt ___.", a: ["Pangäa", "Pangaea", "Pangea"], e: "Pangäa bedeutet „ganze Erde“." },
    { t: "mc", q: "Wie schnell bewegen sich Erdplatten ungefähr?", o: ["Wenige Millimeter pro Jahrhundert", "Wenige Zentimeter pro Jahr", "Mehrere Meter pro Jahr", "Einen Kilometer pro Jahr"], a: 1, e: "Etwa so schnell, wie Fingernägel wachsen." },
    { t: "match", q: "Ordne die Orte den Plattengrenzen zu.", pairs: [["Island", "Platten driften auseinander"], ["Himalaya", "Kontinente stoßen zusammen"], ["San-Andreas-Verwerfung", "Platten schrammen aneinander vorbei"]], e: "Drei Grenztypen, drei völlig unterschiedliche Landschaften." },
    { t: "tf", q: "Ein Erdbeben der Stärke 7 setzt etwa doppelt so viel Energie frei wie eines der Stärke 6.", a: false, e: "Es sind etwa 32-mal so viel. Die Skala ist logarithmisch." },
    { t: "order", q: "Ordne die Erdschichten von außen nach innen.", o: ["Kruste", "Mantel", "Äußerer Kern", "Innerer Kern"], e: "Der äußere Kern ist flüssig, der innere fest." },
  ],
  tips: ["Doku: „Erde: Die Geschichte unseres Planeten“ oder die BBC-Reihe „Planet Erde“ zeigen Plattentektonik in eindrucksvollen Bildern.", "Schau dir eine Animation der Kontinentaldrift auf YouTube an: Suchbegriff „Pangaea to present“.", "Reisetipp: Im Þingvellir-Nationalpark auf Island kannst du in der Silfra-Spalte zwischen zwei Kontinentalplatten tauchen."],
  fact: "Der Mount Everest ist im Kern **Meeresboden**: Auf seinem Gipfel finden sich Fossilien von Meerestieren.",
});

WF.add({
  id: "er-klima", cat: "erde", min: 7, wiki: "Globale_Erwärmung", tags: ["Klimawandel", "Treibhauseffekt", "CO2", "Wetter", "Paris"],
  title: "Wetter, Klima und Klimawandel",
  hook: "Was der Unterschied zwischen Wetter und Klima ist, wie der Treibhauseffekt funktioniert und was die Zahlen wirklich sagen.",
  cards: [
    { h: "Wetter ist nicht Klima", t: "**Wetter** ist das, was gerade draußen passiert: Regen heute, Sonne morgen. **Klima** ist der langfristige Durchschnitt des Wetters an einem Ort, üblicherweise über mindestens **30 Jahre** gemessen. Ein Spruch fasst es gut zusammen: **Klima ist, was du erwartest, Wetter ist, was du bekommst.**\n\nDeshalb widerlegt ein kalter Winter auch nicht die Erderwärmung. Ein einzelner Tag sagt über das Klima so wenig aus wie ein einzelnes Spiel über die Bilanz einer ganzen Saison. Entscheidend sind die **Trends** über Jahrzehnte und die Häufung von Extremen.", merke: "Klima ist der Durchschnitt des Wetters über mindestens 30 Jahre." },
    { h: "Der natürliche Treibhauseffekt", t: "Sonnenlicht erwärmt die Erdoberfläche. Die Erde strahlt die Wärme als unsichtbare **Infrarotstrahlung** wieder ab. Bestimmte Gase in der Atmosphäre, die **Treibhausgase**, halten einen Teil davon zurück, wie eine Decke. Die wichtigsten sind **Wasserdampf**, **Kohlendioxid (CO₂)** und **Methan**.\n\nDieser Effekt ist lebenswichtig: Ohne ihn läge die Durchschnittstemperatur auf der Erde bei etwa **minus 18 Grad** statt bei rund **plus 15 Grad**. Schon 1896 berechnete der schwedische Chemiker **Svante Arrhenius**, dass mehr CO₂ in der Luft die Erde erwärmen müsste. Die Grundphysik ist also seit über 100 Jahren bekannt.", merke: "Ohne natürlichen Treibhauseffekt wäre die Erde im Schnitt etwa minus 18 Grad kalt." },
    { h: "Was der Mensch verändert", t: "Seit der Industrialisierung verbrennt der Mensch Kohle, Öl und Gas. Dabei wird Kohlenstoff frei, der über Jahrmillionen im Boden gespeichert war. Vor der Industrialisierung enthielt die Luft rund **280 ppm** CO₂ (Teilchen pro Million). Heute sind es über **420 ppm**, so viel wie seit Hunderttausenden Jahren nicht.\n\nDie globale Durchschnittstemperatur ist seither um gut **1,2 Grad** gestiegen. **2024** war laut dem EU-Klimadienst Copernicus das erste Kalenderjahr, das im Mittel mehr als **1,5 Grad** über dem vorindustriellen Niveau lag. Der Weltklimarat **IPCC** stellt fest, dass der Mensch die Erwärmung **eindeutig** verursacht hat.", merke: "Der CO₂-Gehalt stieg von etwa 280 auf über 420 ppm. Die Erde ist rund 1,2 Grad wärmer.",
      check: { q: "Welche Aussage stimmt?", o: ["Der Treibhauseffekt an sich ist natürlich und lebenswichtig, der Mensch verstärkt ihn", "Der Treibhauseffekt wurde erst durch den Menschen erzeugt", "CO₂ hat keinen Einfluss auf die Temperatur"], a: 0, e: "Das Problem ist nicht der Effekt selbst, sondern seine Verstärkung durch zusätzliche Treibhausgase." } },
    { h: "Die Folgen", t: "Ein Grad klingt wenig, ist es aber nicht. Wärmere Luft kann mehr Wasser aufnehmen: Pro Grad etwa **7 Prozent** mehr. Deshalb werden **Starkregen** heftiger, wie 2021 bei der Flutkatastrophe im **Ahrtal**. Gleichzeitig werden **Hitzewellen** und **Dürren** häufiger.\n\nDer **Meeresspiegel** steigt, weil sich Wasser bei Erwärmung ausdehnt und Gletscher und Eisschilde schmelzen. Die Alpengletscher haben einen großen Teil ihres Volumens bereits verloren. Forschende warnen außerdem vor **Kipppunkten**: Schwellen, ab denen sich Veränderungen selbst verstärken und kaum noch umkehrbar sind, etwa beim Eisschild Grönlands, beim Amazonas-Regenwald oder beim auftauenden **Permafrost**, der zusätzliches Methan freisetzt.", merke: "Pro Grad Erwärmung kann die Luft etwa 7 Prozent mehr Wasser aufnehmen. Das verstärkt Starkregen." },
    { h: "Was getan wird", t: "**2015** einigten sich fast alle Staaten der Welt im **Pariser Klimaabkommen** darauf, die Erwärmung auf deutlich **unter 2 Grad** zu begrenzen und Anstrengungen für **1,5 Grad** zu unternehmen. Deutschland will bis **2045** klimaneutral sein, also nicht mehr Treibhausgase ausstoßen, als wieder gebunden werden.\n\nDie größten Hebel liegen bei **Strom**, **Verkehr**, **Heizen** und **Industrie**. Beim Strom hat sich viel bewegt: In Deutschland stammt inzwischen über die Hälfte aus erneuerbaren Energien wie Wind und Sonne. Solar- und Windstrom sind in den vergangenen 15 Jahren drastisch billiger geworden. Klimaschutz ist daher längst nicht mehr nur eine Frage des Verzichts, sondern auch der Technik.", merke: "Das Pariser Abkommen von 2015 zielt auf deutlich unter 2 Grad, möglichst 1,5 Grad." },
  ],
  quiz: [
    { t: "mc", q: "Über welchen Zeitraum wird Klima üblicherweise betrachtet?", o: ["Eine Woche", "Ein Jahr", "Mindestens 30 Jahre", "1.000 Jahre"], a: 2, e: "Erst über Jahrzehnte lassen sich Trends vom normalen Wetterchaos unterscheiden." },
    { t: "tf", q: "Ohne den natürlichen Treibhauseffekt wäre die Erde deutlich kälter.", a: true, e: "Statt rund plus 15 Grad wären es im Schnitt etwa minus 18 Grad." },
    { t: "gap", q: "Das Klimaabkommen von 2015 wurde in der Stadt ___ beschlossen.", a: ["Paris"], e: "Ziel: deutlich unter 2 Grad, möglichst 1,5 Grad Erwärmung." },
    { t: "match", q: "Ordne zu.", pairs: [["Svante Arrhenius", "Berechnete 1896 den CO₂-Effekt"], ["Kipppunkt", "Selbstverstärkende Veränderung"], ["IPCC", "Weltklimarat"], ["Permafrost", "Gefrorener Boden, der Methan speichert"]], e: "Begriffe, die in jeder Klimadebatte auftauchen." },
    { t: "mc", q: "Warum werden Starkregen bei Erwärmung heftiger?", o: ["Weil warme Luft mehr Wasser aufnehmen kann", "Weil es mehr Wolken über Städten gibt", "Weil das Meer salziger wird", "Weil die Sonne stärker scheint"], a: 0, e: "Etwa 7 Prozent mehr Wasserdampf pro Grad, der irgendwann als Regen herunterkommt." },
  ],
  tips: ["Schau dir die „Warming Stripes“ von Ed Hawkins an: Ein einziges Bild aus farbigen Streifen zeigt die Erwärmung seit 1850.", "Rechne deinen eigenen CO₂-Fußabdruck mit dem Rechner des Umweltbundesamts aus und finde deinen größten Hebel.", "Buch: „Wie wir die Klimakatastrophe verhindern“ von Bill Gates gibt einen nüchternen Überblick über technische Lösungen."],
  fact: "Ein einziger großer Gewittersturm kann so viel Energie umsetzen wie **mehrere Atombomben**. Das Wetter ist die größte Wärmemaschine der Erde.",
});

WF.add({
  id: "er-ozeane", cat: "erde", min: 6, wiki: "Weltmeer", tags: ["Meer", "Ozean", "Tiefsee", "Golfstrom", "Korallen"],
  title: "Die Ozeane: Der unbekannte Planet",
  hook: "Sie bedecken fast drei Viertel der Erde, und doch kennen wir die Oberfläche des Mars besser als den Meeresboden.",
  cards: [
    { h: "Ein blauer Planet", t: "Rund **71 Prozent** der Erdoberfläche sind von Wasser bedeckt. Davon sind etwa **97 Prozent** Salzwasser. Das meiste Süßwasser ist in Eis und Gletschern gebunden, nur ein winziger Bruchteil fließt in Flüssen und Seen.\n\nMan unterscheidet fünf Ozeane: **Pazifik**, **Atlantik**, **Indischer Ozean**, **Südlicher Ozean** rund um die Antarktis und **Arktischer Ozean**. Der Pazifik allein ist größer als alle Landflächen der Erde zusammen. Erstaunlich: Der Meeresboden ist schlechter erforscht als die Oberfläche des Mars. Nur ein Teil davon ist in hoher Auflösung kartiert.", merke: "71 Prozent der Erde sind Wasser. Der Pazifik ist größer als alle Landflächen zusammen." },
    { h: "Elf Kilometer in die Tiefe", t: "Im Durchschnitt ist der Ozean etwa **3.700 Meter** tief. Die tiefste Stelle liegt im **Marianengraben** im westlichen Pazifik: das **Challengertief** mit rund **11.000 Metern**. Würde man den Mount Everest hineinstellen, läge sein Gipfel noch über zwei Kilometer unter Wasser.\n\nDort unten herrscht ein Druck von über 1.000 bar, als würde ein Elefant auf deinem Daumen stehen, mal hundert. **1960** erreichten der Schweizer **Jacques Piccard** und der US-Amerikaner **Don Walsh** mit dem Tauchboot **Trieste** als erste Menschen den Grund. Und selbst dort gibt es Leben.", merke: "Der Marianengraben ist rund 11.000 Meter tief, tiefer als der Everest hoch ist." },
    { h: "Das globale Förderband", t: "Die Ozeane sind ständig in Bewegung. An der Oberfläche treiben Winde Strömungen an. Dazu kommt eine riesige Umwälzung in der Tiefe, die **thermohaline Zirkulation**: Kaltes, salziges Wasser ist schwerer und sinkt im Nordatlantik ab, fließt am Boden um den Globus und steigt anderswo wieder auf. Ein Durchlauf dauert rund tausend Jahre.\n\nFür Europa besonders wichtig ist der **Golfstrom** und seine Verlängerung, der Nordatlantikstrom. Er transportiert warmes Wasser aus der Karibik nach Nordeuropa. Deshalb ist es in Deutschland deutlich milder als in Kanada auf derselben geografischen Breite. Forschende beobachten, dass sich diese Umwälzung durch die Erwärmung abschwächen könnte.", merke: "Der Golfstrom bringt Wärme nach Europa. Deshalb ist es hier milder als in Kanada.",
      check: { q: "Warum ist es in Deutschland wärmer als in Kanada auf gleicher Breite?", o: ["Weil der Golfstrom warmes Wasser nach Europa bringt", "Weil Deutschland näher an der Sonne liegt", "Weil es in Deutschland mehr Städte gibt"], a: 0, e: "Die Meeresströmung wirkt wie eine riesige Warmwasserheizung für Nordeuropa." } },
    { h: "Leben im Meer", t: "Im Meer lebt das größte Tier, das es je gab: der **Blauwal**, bis zu 30 Meter lang und deutlich schwerer als jeder Dinosaurier. Sein Herz ist so groß wie ein Kleinwagen.\n\n**Korallenriffe** bedecken weniger als ein Prozent des Meeresbodens, beherbergen aber rund ein Viertel aller Meeresarten. Das größte ist das **Great Barrier Reef** vor Australien, aus dem All sichtbar. In der **Tiefsee**, wo kein Sonnenlicht hinkommt, erzeugen viele Lebewesen ihr eigenes Licht. Diese **Biolumineszenz** nutzen sie zum Jagen, Tarnen oder Anlocken von Partnern.", merke: "Korallenriffe bedecken unter 1 Prozent des Meeresbodens, beherbergen aber etwa ein Viertel der Meeresarten." },
    { h: "Ein Ozean unter Stress", t: "Die Meere sind die großen Puffer des Klimas: Sie haben über **90 Prozent** der zusätzlichen Wärme aufgenommen, die durch den Treibhauseffekt entstanden ist, und etwa ein Viertel des ausgestoßenen CO₂. Das hat Folgen. Das CO₂ macht das Wasser **saurer**, was Muscheln und Korallen das Bauen ihrer Kalkschalen erschwert. Hitze lässt Korallen ihre Algen abstoßen, sie **bleichen aus** und können sterben.\n\nDazu kommen **Überfischung** und **Plastik**: Im Nordpazifik treibt ein riesiger Müllstrudel, der **Great Pacific Garbage Patch**. Ein Großteil des Plastiks zerfällt in winziges **Mikroplastik**, das inzwischen in Fischen und selbst im menschlichen Körper nachgewiesen wurde.", merke: "Die Meere haben über 90 Prozent der zusätzlichen Wärme aufgenommen." },
  ],
  quiz: [
    { t: "mc", q: "Wie viel Prozent der Erdoberfläche sind von Wasser bedeckt?", o: ["Etwa 50 Prozent", "Etwa 71 Prozent", "Etwa 85 Prozent", "Etwa 97 Prozent"], a: 1, e: "97 Prozent ist der Anteil des Salzwassers am gesamten Wasser." },
    { t: "gap", q: "Die tiefste Stelle der Ozeane liegt im ___graben.", a: ["Marianen", "Marianengraben"], e: "Das Challengertief ist rund 11.000 Meter tief." },
    { t: "tf", q: "Korallenriffe bedecken einen großen Teil des Meeresbodens.", a: false, e: "Weniger als ein Prozent, aber sie beherbergen etwa ein Viertel aller Meeresarten." },
    { t: "match", q: "Ordne zu.", pairs: [["Golfstrom", "Bringt Wärme nach Europa"], ["Biolumineszenz", "Selbst erzeugtes Licht"], ["Versauerung", "Folge von CO₂ im Wasser"], ["Trieste", "Tauchboot von 1960"]], e: "Vier Begriffe aus der Welt der Ozeane." },
    { t: "mc", q: "Welches ist das größte Tier, das je gelebt hat?", o: ["Tyrannosaurus rex", "Blauwal", "Pottwal", "Argentinosaurus"], a: 1, e: "Blauwale werden bis zu 30 Meter lang und sind schwerer als jeder bekannte Dinosaurier." },
  ],
  tips: ["Doku: „Blue Planet II“ von der BBC, mit unglaublichen Aufnahmen aus der Tiefsee.", "Ausflug: Das Ozeaneum in Stralsund gehört zu den besten Meeresmuseen Europas.", "Achte eine Woche lang darauf, wie viel Einwegplastik du benutzt, und such dir eine Sache aus, die du ersetzen kannst."],
  fact: "Im Meer gibt es **Flüsse und Seen unter Wasser**: Salzlaken, die schwerer als das umgebende Wasser sind, bilden am Meeresboden eigene Ufer.",
});

/* ===================== POLITIK & RECHT ===================== */
WF.add({
  id: "po-demokratie", cat: "politik", min: 7, wiki: "Grundgesetz_für_die_Bundesrepublik_Deutschland", tags: ["Grundgesetz", "Bundestag", "Wahlen", "Gewaltenteilung", "Deutschland"],
  title: "Wie Deutschland regiert wird",
  hook: "Wer macht die Gesetze, wer wählt den Kanzler und warum kann ein Gericht in Karlsruhe die Regierung stoppen?",
  cards: [
    { h: "Ein Provisorium, das blieb", t: "Am **23. Mai 1949** trat das **Grundgesetz** in Kraft. Es hieß bewusst nicht „Verfassung“, weil es nur ein Provisorium für Westdeutschland sein sollte, bis Deutschland wiedervereinigt ist. Es bewährte sich so gut, dass es seit **1990** für ganz Deutschland gilt.\n\nDie ersten Artikel enthalten die **Grundrechte**, beginnend mit dem berühmten Satz: **„Die Würde des Menschen ist unantastbar.“** Artikel 20 legt die Grundprinzipien fest: Deutschland ist eine **Demokratie**, ein **Sozialstaat**, ein **Bundesstaat** und ein **Rechtsstaat**. Diese Prinzipien und die Menschenwürde dürfen durch die **Ewigkeitsklausel** in Artikel 79 nicht einmal mit einer Zweidrittelmehrheit abgeschafft werden.", merke: "Das Grundgesetz gilt seit 1949. Menschenwürde und Grundprinzipien sind durch die Ewigkeitsklausel geschützt." },
    { h: "Drei Gewalten", t: "Damit niemand zu viel Macht bekommt, ist die Staatsgewalt aufgeteilt. Die Idee stammt vom französischen Philosophen **Montesquieu** (1748).\n\nDie **Legislative** macht Gesetze: der **Bundestag**, mit Mitwirkung des **Bundesrats**, in dem die Länder vertreten sind. Die **Exekutive** führt die Gesetze aus: die **Bundesregierung** mit Kanzler und Ministern, dazu Behörden und Polizei. Die **Judikative** spricht Recht: die unabhängigen **Gerichte**.\n\nZusätzlich kontrollieren sich die Gewalten gegenseitig. Der Bundestag kann die Regierung befragen, Gerichte können Behördenentscheidungen aufheben, und die freie **Presse** gilt als „vierte Gewalt“.", merke: "Legislative macht Gesetze, Exekutive führt sie aus, Judikative spricht Recht." },
    { h: "Wählen mit zwei Stimmen", t: "Der **Bundestag** wird in der Regel alle **vier Jahre** gewählt, wählen darf man ab **18**. Jeder hat zwei Stimmen. Mit der **Erststimme** wählst du eine Person für deinen Wahlkreis. Die **Zweitstimme** geht an eine Partei und ist die wichtigere: Sie bestimmt, wie viele Sitze eine Partei insgesamt bekommt.\n\nParteien brauchen bundesweit mindestens **5 Prozent** der Zweitstimmen, um einzuziehen. Seit der Wahlrechtsreform ist der Bundestag auf **630 Sitze** begrenzt. Wichtig: Den **Bundeskanzler** wählt nicht das Volk direkt, sondern der **Bundestag**. Meist braucht es dafür eine **Koalition** aus mehreren Parteien, die zusammen die Mehrheit haben.", merke: "Die Zweitstimme entscheidet über die Sitzverteilung. Den Kanzler wählt der Bundestag.",
      check: { q: "Wer wählt den Bundeskanzler?", o: ["Der Bundestag", "Das Volk direkt", "Der Bundespräsident allein"], a: 0, e: "Der Bundespräsident schlägt eine Person vor, gewählt wird sie vom Bundestag." } },
    { h: "Präsident, Länder, Föderalismus", t: "Das Staatsoberhaupt ist der **Bundespräsident**. Er hat vor allem repräsentative Aufgaben: Er unterschreibt Gesetze, ernennt den Kanzler und hält Reden, die Orientierung geben sollen. Gewählt wird er für **fünf Jahre** von der **Bundesversammlung**, die aus den Bundestagsabgeordneten und ebenso vielen Vertretern der Länder besteht.\n\nDeutschland ist ein **Bundesstaat** mit **16 Ländern**, jedes mit eigenem Parlament und eigener Regierung. Das nennt man **Föderalismus**. Manche Bereiche sind Ländersache, etwa **Schule**, **Polizei** und Hochschulen. Deshalb unterscheiden sich Abiturprüfungen und Ferienzeiten von Land zu Land, und deshalb bewirbt man sich bei der Polizei meist bei einem Bundesland.", merke: "Schule und Polizei sind in Deutschland überwiegend Ländersache." },
    { h: "Die Hüter der Verfassung", t: "Das **Bundesverfassungsgericht** in **Karlsruhe** wacht darüber, dass Staat und Gesetze das Grundgesetz einhalten. Es kann Gesetze für **verfassungswidrig** erklären, selbst wenn sie mit großer Mehrheit beschlossen wurden. Das ist schon oft passiert, etwa 2023, als es einen Umbau des Bundeshaushalts in Milliardenhöhe stoppte.\n\nJeder Mensch kann eine **Verfassungsbeschwerde** einreichen, wenn er sich vom Staat in seinen Grundrechten verletzt sieht, ohne Anwalt und kostenlos. Allerdings erst, wenn der normale Rechtsweg ausgeschöpft ist. Nur ein kleiner Teil der Beschwerden hat Erfolg, doch die Möglichkeit macht das Gericht zu einem der angesehensten Organe des Staates.", merke: "Das Bundesverfassungsgericht in Karlsruhe kann Gesetze für verfassungswidrig erklären." },
  ],
  quiz: [
    { t: "gap", q: "Das Grundgesetz trat am 23. Mai ___ in Kraft.", a: ["1949"], e: "Der 23. Mai ist deshalb der Verfassungstag." },
    { t: "match", q: "Ordne die Institutionen den Gewalten zu.", pairs: [["Bundestag", "Legislative"], ["Bundesregierung", "Exekutive"], ["Bundesverfassungsgericht", "Judikative"]], e: "Gewaltenteilung verhindert, dass jemand zu viel Macht bekommt." },
    { t: "mc", q: "Welche Stimme entscheidet über die Sitzverteilung im Bundestag?", o: ["Die Erststimme", "Die Zweitstimme", "Beide gleich", "Die Stimme des Bundespräsidenten"], a: 1, e: "Die Zweitstimme geht an eine Partei und bestimmt ihren Anteil an den Sitzen." },
    { t: "tf", q: "Der Bundeskanzler wird in Deutschland direkt vom Volk gewählt.", a: false, e: "Er wird vom Bundestag gewählt." },
    { t: "mc", q: "Wo sitzt das Bundesverfassungsgericht?", o: ["Berlin", "Bonn", "Karlsruhe", "Leipzig"], a: 2, e: "In Leipzig sitzt das Bundesverwaltungsgericht, in Karlsruhe auch der Bundesgerichtshof." },
  ],
  tips: ["Lies die Artikel 1 bis 20 des Grundgesetzes. Die Bundeszentrale für politische Bildung (bpb.de) verschickt kostenlose gedruckte Exemplare.", "Probier vor der nächsten Wahl den Wahl-O-Mat der bpb aus und lies danach die Begründungen der Parteien.", "Schau dir eine Bundestagsdebatte auf bundestag.de an, zum Beispiel eine Regierungsbefragung."],
  fact: "Das Grundgesetz wurde von **65 Mitgliedern des Parlamentarischen Rates** ausgearbeitet, darunter nur **vier Frauen**. Ihnen ist der Satz „Männer und Frauen sind gleichberechtigt“ zu verdanken.",
});

WF.add({
  id: "po-eu", cat: "politik", min: 6, wiki: "Europäische_Union", tags: ["EU", "Europa", "Euro", "Brüssel", "Schengen"],
  title: "Die Europäische Union",
  hook: "Aus Kohle und Stahl wurde der größte Binnenmarkt der Welt. Wie die EU funktioniert und wo sie deinen Alltag prägt.",
  cards: [
    { h: "Nie wieder Krieg", t: "Nach zwei Weltkriegen suchten europäische Politiker einen Weg, Kriege zwischen ihren Ländern unmöglich zu machen. Der französische Außenminister **Robert Schuman** schlug **1950** vor, die Kohle- und Stahlproduktion von Frankreich und Deutschland gemeinsam zu verwalten. Ohne eigene Kontrolle über diese Rüstungsrohstoffe wäre ein Krieg praktisch nicht mehr zu führen.\n\n**1951** gründeten sechs Länder die **Montanunion**: Frankreich, die Bundesrepublik, Italien, Belgien, die Niederlande und Luxemburg. **1957** folgte mit den **Römischen Verträgen** die Europäische Wirtschaftsgemeinschaft. Der Vertrag von **Maastricht** schuf **1993** die **Europäische Union**. 2012 erhielt die EU den Friedensnobelpreis.", merke: "Die EU begann 1951 mit der Montanunion aus sechs Ländern. Die EU selbst gibt es seit 1993." },
    { h: "27 Länder, 450 Millionen Menschen", t: "Heute hat die EU **27 Mitgliedstaaten** mit rund **450 Millionen** Einwohnern. Großbritannien stimmte **2016** in einem Referendum für den Austritt und verließ die EU Anfang **2020**, der sogenannte **Brexit**.\n\nDas Herzstück ist der **Binnenmarkt** mit vier Freiheiten: freier Verkehr von **Waren**, **Dienstleistungen**, **Kapital** und **Personen**. Als EU-Bürger darfst du in jedem Mitgliedsland leben, studieren und arbeiten. Im **Schengen-Raum** gibt es in der Regel keine Kontrollen an den Binnengrenzen. Und mit dem **Euro** zahlt eine Mehrheit der Mitglieder mit einer gemeinsamen Währung, als Bargeld seit **2002**.", merke: "Die vier Freiheiten: Waren, Dienstleistungen, Kapital und Personen." },
    { h: "Wer in Brüssel was macht", t: "Die EU hat mehrere Organe, die sich leicht verwechseln lassen:\n\nDie **Europäische Kommission** schlägt Gesetze vor und überwacht ihre Einhaltung. Sie ist so etwas wie die Regierung der EU, an ihrer Spitze steht seit 2019 **Ursula von der Leyen**.\n\nDas **Europäische Parlament** wird alle fünf Jahre direkt von den Bürgern gewählt. In Deutschland darf man seit 2024 schon ab **16** mitwählen.\n\nDer **Rat der EU** besteht aus den Fachministern der Mitgliedstaaten. Parlament und Rat beschließen Gesetze gemeinsam.\n\nDer **Europäische Rat** ist das Gipfeltreffen der Staats- und Regierungschefs und gibt die große Richtung vor. Der **Europäische Gerichtshof** in Luxemburg sorgt für eine einheitliche Auslegung des EU-Rechts.", merke: "Die Kommission schlägt Gesetze vor, Parlament und Rat beschließen sie.",
      check: { q: "Welches EU-Organ wird direkt von den Bürgern gewählt?", o: ["Das Europäische Parlament", "Die Europäische Kommission", "Der Europäische Rat"], a: 0, e: "Die Kommission wird vorgeschlagen und vom Parlament bestätigt, der Europäische Rat besteht aus den Regierungschefs." } },
    { h: "Die EU in deinem Alltag", t: "Viele Dinge, die selbstverständlich wirken, kommen aus Brüssel. Seit **2017** zahlst du in der EU keine **Roaming-Gebühren** mehr, wenn du im Ausland telefonierst oder surfst. Das Austauschprogramm **Erasmus** hat seit 1987 Millionen Studierenden, Azubis und Schülern Aufenthalte im Ausland ermöglicht.\n\nDie **Datenschutz-Grundverordnung (DSGVO)** von 2018 gibt dir das Recht, zu erfahren, welche Daten Firmen über dich speichern. Seit Ende 2024 müssen neue Handys und viele andere Geräte einen **USB-C-Anschluss** haben. Und wenn dein Flug stark verspätet ist, stehen dir nach EU-Recht oft **Entschädigungen** von bis zu 600 Euro zu.", merke: "Kein Roaming, Erasmus, DSGVO, USB-C und Fluggastrechte kommen von der EU." },
    { h: "Streitpunkte", t: "Die EU ist nicht unumstritten. Kritiker bemängeln **Bürokratie** und komplizierte Entscheidungswege: In wichtigen Fragen wie der Außenpolitik müssen oft **alle 27** zustimmen, ein einzelnes Land kann blockieren. Andere sehen ein **Demokratiedefizit**, weil die Kommission nicht direkt gewählt wird.\n\nGroße Debatten drehen sich um **Migration**, die gemeinsame **Verteidigung** seit dem russischen Angriff auf die Ukraine, den Umgang mit Mitgliedern, die rechtsstaatliche Regeln verletzen, und mögliche **Erweiterungen**, etwa um die Ukraine, Moldau oder Länder des Westbalkans. Wie eng die Staaten zusammenarbeiten sollen, bleibt eine der großen politischen Fragen Europas.", merke: "In wichtigen Fragen wie der Außenpolitik gilt oft Einstimmigkeit, ein Land kann blockieren." },
  ],
  quiz: [
    { t: "mc", q: "Wie viele Mitgliedstaaten hat die EU heute?", o: ["15", "25", "27", "30"], a: 2, e: "Seit dem Austritt Großbritanniens 2020 sind es 27." },
    { t: "order", q: "Bring die Schritte der europäischen Einigung in die richtige Reihenfolge.", o: ["Montanunion", "Römische Verträge", "Vertrag von Maastricht", "Euro als Bargeld", "Brexit"], e: "1951, 1957, 1993, 2002, 2020." },
    { t: "match", q: "Ordne die EU-Organe ihren Aufgaben zu.", pairs: [["Kommission", "Schlägt Gesetze vor"], ["Parlament", "Direkt gewählt, beschließt Gesetze mit"], ["Europäischer Rat", "Gipfel der Regierungschefs"], ["Gerichtshof", "Legt EU-Recht einheitlich aus"]], e: "Das Zusammenspiel dieser Organe macht die EU kompliziert, aber auch ausgewogen." },
    { t: "tf", q: "Seit 2017 zahlt man in der EU keine Roaming-Gebühren mehr.", a: true, e: "Telefonieren und Surfen im EU-Ausland kostet seitdem so viel wie zu Hause." },
    { t: "gap", q: "Der Vorschlag von 1950, Kohle und Stahl gemeinsam zu verwalten, stammte von Robert ___.", a: ["Schuman"], e: "Der 9. Mai, der Tag seiner Erklärung, ist heute Europatag." },
  ],
  tips: ["Plan einen Auslandsaufenthalt: Erasmus+ gibt es nicht nur für Studierende, sondern auch für Azubis und Freiwilligendienste.", "Frag bei einer App oder einem Shop nach der DSGVO-Auskunft, welche Daten über dich gespeichert sind. Du hast ein Recht darauf.", "Schau dir auf europarl.europa.eu an, welche Abgeordneten aus deiner Region im Europaparlament sitzen."],
  fact: "Das Europäische Parlament **pendelt**: Es tagt meist in Brüssel, muss aber laut Verträgen zwölfmal im Jahr für Plenarsitzungen nach **Straßburg** umziehen.",
});

WF.add({
  id: "po-rechte", cat: "politik", min: 7, wiki: "Geschäftsfähigkeit", tags: ["Recht", "Verträge", "Widerruf", "Arbeitsrecht", "Grundrechte"],
  title: "Deine Rechte im Alltag",
  hook: "Online-Kauf zurückschicken, Urlaub im Minijob, Meinungsfreiheit: Was das Gesetz dir wirklich garantiert. Allgemeinwissen, keine Rechtsberatung.",
  cards: [
    { h: "Mit 18 voll verantwortlich", t: "Rechtlich ändert sich mit dem 18. Geburtstag viel: Du bist **volljährig** und **voll geschäftsfähig**. Du kannst Verträge allein abschließen, etwa für Handy, Wohnung oder Kredit, und musst sie dann auch erfüllen.\n\nZwischen **7 und 17** ist man **beschränkt geschäftsfähig**: Größere Verträge brauchen die Zustimmung der Eltern. Eine Ausnahme ist der **Taschengeldparagraf** (§ 110 BGB): Was ein Minderjähriger mit seinem Taschengeld sofort bezahlt, ist wirksam. Ein Handyvertrag mit monatlichen Raten fällt aber nicht darunter, weil er nicht sofort vollständig bezahlt wird.", merke: "Ab 18 ist man voll geschäftsfähig. Zwischen 7 und 17 beschränkt." },
    { h: "Kaufen und zurückgeben", t: "Bei Käufen **online** oder per Telefon hast du in der Regel ein **Widerrufsrecht von 14 Tagen**. Du kannst den Vertrag ohne Begründung widerrufen und die Ware zurückschicken. Die Frist beginnt meist mit dem Erhalt der Ware.\n\nIm **Laden** gibt es dagegen **kein gesetzliches Umtauschrecht**. Wenn ein Geschäft trotzdem umtauscht, ist das freiwillige Kulanz. Ist die Ware aber **mangelhaft**, gilt überall die **Gewährleistung** von **zwei Jahren**. Tritt ein Mangel im ersten Jahr auf, wird vermutet, dass er schon beim Kauf da war. Der Händler muss dann das Gegenteil beweisen. Wichtig: Gewährleistung ist gesetzlich und gilt gegenüber dem Händler, eine **Garantie** ist ein freiwilliges Versprechen des Herstellers.", merke: "Online 14 Tage Widerruf, im Laden kein gesetzliches Umtauschrecht, Gewährleistung zwei Jahre." },
    { h: "Rechte bei der Arbeit", t: "Auch im **Minijob** hast du fast alle Rechte wie andere Beschäftigte. Es gilt der **gesetzliche Mindestlohn**, der seit 2026 bei **13,90 Euro** pro Stunde liegt. Du hast Anspruch auf **bezahlten Urlaub**: gesetzlich mindestens vier Wochen im Jahr, anteilig für deine Arbeitstage. Wer zum Beispiel zwei Tage pro Woche arbeitet, hat mindestens acht Urlaubstage.\n\nBist du krank, bekommst du **Lohnfortzahlung** für bis zu sechs Wochen, wenn das Arbeitsverhältnis schon vier Wochen besteht. Meist brauchst du ab dem vierten Krankheitstag eine Krankschreibung, der Arbeitgeber darf sie aber auch früher verlangen. Ein **Arbeitsvertrag** kann mündlich zustande kommen, die wichtigsten Bedingungen muss der Arbeitgeber dir aber schriftlich geben.", merke: "Auch Minijobber haben Anspruch auf Mindestlohn, Urlaub und Lohnfortzahlung bei Krankheit.",
      check: { q: "Du arbeitest im Minijob. Hast du Anspruch auf bezahlten Urlaub?", o: ["Ja, anteilig zu deinen Arbeitstagen", "Nein, Urlaub gibt es nur in Vollzeit", "Nur wenn es im Vertrag steht"], a: 0, e: "Der gesetzliche Urlaubsanspruch gilt für alle Beschäftigten, auch für Minijobber." } },
    { h: "Meinungsfreiheit und ihre Grenzen", t: "**Artikel 5** des Grundgesetzes garantiert die **Meinungsfreiheit**. Du darfst deine Meinung frei sagen, schreiben und verbreiten, auch scharfe Kritik an der Regierung.\n\nWichtig zu verstehen: Die Meinungsfreiheit schützt dich **vor dem Staat**. Sie schützt dich nicht davor, dass andere widersprechen, dich kritisieren oder eine Plattform deinen Beitrag nach ihren Regeln löscht. Und sie hat **Grenzen**: Beleidigung, Verleumdung, Volksverhetzung oder Aufrufe zu Straftaten sind nicht erlaubt, auch nicht online. Ein Kommentar unter einem Instagram-Post kann genauso strafbar sein wie ein Satz auf der Straße.", merke: "Meinungsfreiheit schützt vor dem Staat, aber nicht vor Widerspruch. Beleidigung bleibt strafbar." },
    { h: "Strafrecht: Unschuldig bis zum Beweis", t: "Im deutschen Recht gilt die **Unschuldsvermutung**: Jeder gilt als unschuldig, bis ein Gericht ihn rechtskräftig verurteilt hat. Wer einer Straftat **beschuldigt** wird, hat das Recht zu **schweigen** und einen **Anwalt** hinzuzuziehen. Niemand muss sich selbst belasten.\n\n**Strafmündig** ist man ab **14 Jahren**. Für 14- bis 17-Jährige gilt das **Jugendstrafrecht**, bei dem Erziehung im Vordergrund steht. Für **Heranwachsende** zwischen 18 und 20 kann es je nach Reife ebenfalls angewendet werden. Zu unterscheiden ist außerdem: Das **Strafrecht** regelt, was der Staat bestraft. Das **Zivilrecht** regelt Streit zwischen Bürgern, etwa um Geld, Mietverträge oder Schadenersatz.", merke: "Strafmündig ist man ab 14. Beschuldigte dürfen schweigen und einen Anwalt verlangen." },
  ],
  quiz: [
    { t: "mc", q: "Wie lange kannst du einen Online-Kauf in der Regel ohne Begründung widerrufen?", o: ["3 Tage", "7 Tage", "14 Tage", "30 Tage"], a: 2, e: "Das Widerrufsrecht bei Fernabsatzverträgen beträgt in der Regel 14 Tage." },
    { t: "tf", q: "Im Laden gibt es ein gesetzliches Recht, nicht mangelhafte Ware umzutauschen.", a: false, e: "Ein Umtausch ohne Mangel ist reine Kulanz des Geschäfts." },
    { t: "gap", q: "Strafmündig ist man in Deutschland ab ___ Jahren.", a: ["14", "vierzehn"], e: "Für 14- bis 17-Jährige gilt das Jugendstrafrecht." },
    { t: "match", q: "Ordne zu.", pairs: [["Gewährleistung", "Gesetzlich, zwei Jahre, gegenüber dem Händler"], ["Garantie", "Freiwilliges Versprechen des Herstellers"], ["Taschengeldparagraf", "Sofort bezahlte Käufe Minderjähriger"], ["Unschuldsvermutung", "Unschuldig bis zur Verurteilung"]], e: "Diese Begriffe werden im Alltag oft verwechselt." },
    { t: "mc", q: "Wovor schützt die Meinungsfreiheit nach Artikel 5?", o: ["Vor jeder Form von Kritik", "Vor Eingriffen des Staates in deine Meinungsäußerung", "Vor Löschungen auf Social Media", "Vor Strafen wegen Beleidigung"], a: 1, e: "Sie ist ein Abwehrrecht gegen den Staat." },
  ],
  tips: ["Hinweis: Diese Lektion vermittelt Allgemeinwissen und ersetzt keine Rechtsberatung. Bei konkreten Problemen helfen Verbraucherzentralen, Gewerkschaften oder die Beratungsstellen der Hochschulen.", "Speichere dir die Seite der Verbraucherzentrale ab. Dort gibt es Musterbriefe für Widerruf und Reklamation.", "Beim nächsten Online-Kauf: Lies einmal bewusst die Widerrufsbelehrung. Sie steht in jedem Shop."],
  fact: "Ein Vertrag braucht in Deutschland meist **keine Unterschrift**: Schon wenn du beim Bäcker ein Brötchen bestellst und bezahlst, hast du einen gültigen **Kaufvertrag** geschlossen.",
});

